-- ============================================================================
-- POS Desktop - initial schema (SQLite 3.37+)
--
-- Conventions
--   * IDs are TEXT UUIDs generated by the application (UUID v7 recommended).
--   * Timestamps are TEXT ISO-8601 in UTC: 2026-11-12T08:30:00.000Z
--   * Money is INTEGER minor units. For IDR the minor unit is 1 rupiah
--     (currency_minor_unit = 0); for USD it is cents (currency_minor_unit = 2).
--     Never use REAL for money.
--   * Quantities are INTEGER thousandths ("milli"): 1000 = 1 pcs / 1 kg.
--   * Tax rates and percentage discounts are basis points: 1100 = 11.00%.
--   * All tables are STRICT. Foreign keys are ON and must stay ON at runtime.
--   * Single-user, single-register local database. Authorization is enforced
--     in the .NET application services, not in SQLite (there is no RLS).
--
-- This file is the first migration and is executed as one script. If your
-- migration runner already opens a transaction, remove the BEGIN/COMMIT lines.
-- ============================================================================

PRAGMA foreign_keys = ON;
PRAGMA journal_mode = WAL;
PRAGMA synchronous = NORMAL;
PRAGMA busy_timeout = 5000;

BEGIN;

-- ----------------------------------------------------------------------------
-- 1. Migrations, roles, users
-- ----------------------------------------------------------------------------

CREATE TABLE schema_migrations (
  version     INTEGER PRIMARY KEY,
  name        TEXT NOT NULL,
  applied_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
) STRICT;

CREATE TABLE roles (
  id               TEXT PRIMARY KEY,
  name             TEXT NOT NULL COLLATE NOCASE UNIQUE,
  is_admin         INTEGER NOT NULL DEFAULT 0 CHECK (is_admin IN (0,1)),
  permissions_json TEXT NOT NULL DEFAULT '{}',
  created_at       TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at       TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
) STRICT;

CREATE TABLE users (
  id                 TEXT PRIMARY KEY,
  username           TEXT NOT NULL COLLATE NOCASE UNIQUE,
  password_hash      TEXT NOT NULL,
  full_name          TEXT NOT NULL,
  role_id            TEXT NOT NULL REFERENCES roles(id) ON DELETE RESTRICT,
  active             INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
  last_login_at      TEXT,
  failed_login_count INTEGER NOT NULL DEFAULT 0 CHECK (failed_login_count >= 0),
  locked_until       TEXT,
  created_at         TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at         TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
) STRICT;

CREATE INDEX idx_users_role ON users(role_id);
CREATE INDEX idx_users_active ON users(active);

-- ----------------------------------------------------------------------------
-- 2. Company and settings
-- ----------------------------------------------------------------------------

CREATE TABLE company (
  id                  TEXT PRIMARY KEY CHECK (id = 'company'),
  name                TEXT NOT NULL DEFAULT '',
  legal_name          TEXT,
  tax_number          TEXT,
  address             TEXT,
  phone               TEXT,
  email               TEXT,
  logo_path           TEXT,
  currency            TEXT NOT NULL DEFAULT 'IDR',
  currency_minor_unit INTEGER NOT NULL DEFAULT 0
                      CHECK (currency_minor_unit BETWEEN 0 AND 4),
  locale              TEXT NOT NULL DEFAULT 'id-ID',
  timezone            TEXT NOT NULL DEFAULT 'Asia/Jakarta',
  receipt_header      TEXT,
  receipt_footer      TEXT,
  created_at          TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at          TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
) STRICT;

CREATE TABLE settings (
  key         TEXT NOT NULL,
  scope       TEXT NOT NULL DEFAULT 'global'
              CHECK (scope IN ('global','register','user')),
  scope_id    TEXT NOT NULL DEFAULT '',
  value_json  TEXT NOT NULL,
  updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (key, scope, scope_id)
) STRICT;

CREATE INDEX idx_settings_scope ON settings(scope, scope_id);

-- ----------------------------------------------------------------------------
-- 3. Catalog
-- ----------------------------------------------------------------------------

CREATE TABLE product_groups (
  id         TEXT PRIMARY KEY,
  name       TEXT NOT NULL,
  parent_id  TEXT REFERENCES product_groups(id) ON DELETE RESTRICT,
  sort_order INTEGER NOT NULL DEFAULT 0,
  active     INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
) STRICT;

CREATE INDEX idx_product_groups_parent ON product_groups(parent_id);
CREATE UNIQUE INDEX ux_product_groups_root_name
  ON product_groups(name) WHERE parent_id IS NULL;
CREATE UNIQUE INDEX ux_product_groups_child_name
  ON product_groups(parent_id, name) WHERE parent_id IS NOT NULL;

CREATE TABLE products (
  id                   TEXT PRIMARY KEY,
  name                 TEXT NOT NULL,
  code                 TEXT COLLATE NOCASE,
  group_id             TEXT REFERENCES product_groups(id) ON DELETE SET NULL,
  active               INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
  default_qty_milli    INTEGER NOT NULL DEFAULT 1000 CHECK (default_qty_milli > 0),
  is_service           INTEGER NOT NULL DEFAULT 0 CHECK (is_service IN (0,1)),
  age_restriction      INTEGER CHECK (age_restriction IS NULL OR age_restriction BETWEEN 0 AND 100),
  description          TEXT,
  cost_minor           INTEGER NOT NULL DEFAULT 0 CHECK (cost_minor >= 0),
  markup_bp            INTEGER CHECK (markup_bp IS NULL OR markup_bp >= 0),
  price_minor          INTEGER NOT NULL DEFAULT 0 CHECK (price_minor >= 0),
  price_includes_tax   INTEGER NOT NULL DEFAULT 0 CHECK (price_includes_tax IN (0,1)),
  price_change_allowed INTEGER NOT NULL DEFAULT 1 CHECK (price_change_allowed IN (0,1)),
  image_path           TEXT,
  color                TEXT,
  created_at           TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at           TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
) STRICT;

CREATE UNIQUE INDEX ux_products_code ON products(code) WHERE code IS NOT NULL;
CREATE INDEX idx_products_group ON products(group_id);
CREATE INDEX idx_products_name ON products(name);
CREATE INDEX idx_products_active ON products(active);

-- Reusable unit master: pcs, bungkus, renteng, dus, kg, g, L, mL...
-- A product picks its smallest/base unit and any larger selling units here.
CREATE TABLE units (
  id         TEXT PRIMARY KEY,
  name       TEXT NOT NULL COLLATE NOCASE UNIQUE,
  symbol     TEXT,
  active     INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
) STRICT;

CREATE INDEX idx_units_active ON units(active);

-- Every product has one base/smallest unit row (factor 1000). Additional rows
-- are selling variants: 250 g = 250, 1 g = 1, renteng (6 bungkus) = 6000,
-- dus (100 bungkus) = 100000. Stock is always kept in the base unit.
CREATE TABLE product_units (
  id                   TEXT PRIMARY KEY,
  product_id           TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE,
  unit_id              TEXT NOT NULL REFERENCES units(id) ON DELETE RESTRICT,
  factor_to_base_milli INTEGER NOT NULL CHECK (factor_to_base_milli > 0),
  is_base              INTEGER NOT NULL DEFAULT 0 CHECK (is_base IN (0,1)),
  is_default_sale      INTEGER NOT NULL DEFAULT 0 CHECK (is_default_sale IN (0,1)),
  price_minor          INTEGER CHECK (price_minor IS NULL OR price_minor >= 0),
  sort_order           INTEGER NOT NULL DEFAULT 0,
  active               INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
  created_at           TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at           TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  UNIQUE (product_id, unit_id),
  CHECK (is_base = 0 OR factor_to_base_milli = 1000)
) STRICT;

CREATE INDEX idx_product_units_product ON product_units(product_id);
CREATE INDEX idx_product_units_unit ON product_units(unit_id);
CREATE UNIQUE INDEX ux_product_units_base
  ON product_units(product_id) WHERE is_base = 1;
CREATE UNIQUE INDEX ux_product_units_default_sale
  ON product_units(product_id) WHERE is_default_sale = 1;

CREATE TABLE product_barcodes (
  id              TEXT PRIMARY KEY,
  product_unit_id TEXT NOT NULL REFERENCES product_units(id) ON DELETE CASCADE,
  barcode         TEXT NOT NULL COLLATE NOCASE UNIQUE,
  is_primary      INTEGER NOT NULL DEFAULT 0 CHECK (is_primary IN (0,1)),
  created_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
) STRICT;

CREATE INDEX idx_product_barcodes_unit ON product_barcodes(product_unit_id);
CREATE UNIQUE INDEX ux_product_barcodes_primary
  ON product_barcodes(product_unit_id) WHERE is_primary = 1;

CREATE TABLE tax_rates (
  id         TEXT PRIMARY KEY,
  name       TEXT NOT NULL COLLATE NOCASE UNIQUE,
  rate_bp    INTEGER NOT NULL CHECK (rate_bp BETWEEN 0 AND 100000),
  active     INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
  is_default INTEGER NOT NULL DEFAULT 0 CHECK (is_default IN (0,1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
) STRICT;

CREATE UNIQUE INDEX ux_tax_rates_default ON tax_rates(is_default) WHERE is_default = 1;

CREATE TABLE product_taxes (
  product_id  TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE,
  tax_rate_id TEXT NOT NULL REFERENCES tax_rates(id) ON DELETE RESTRICT,
  PRIMARY KEY (product_id, tax_rate_id)
) STRICT;

CREATE INDEX idx_product_taxes_tax ON product_taxes(tax_rate_id);

-- ----------------------------------------------------------------------------
-- 4. Price lists (the paid plugin in the original; native here)
-- ----------------------------------------------------------------------------

CREATE TABLE price_lists (
  id               TEXT PRIMARY KEY,
  name             TEXT NOT NULL COLLATE NOCASE UNIQUE,
  apply_promotions INTEGER NOT NULL DEFAULT 1 CHECK (apply_promotions IN (0,1)),
  active           INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
  created_at       TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at       TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
) STRICT;

-- Absence of a row means "inherit the unit's default price" (which itself
-- falls back to the base price scaled by factor_to_base_milli).
-- The UI shows an inherited price with a "!" marker.
CREATE TABLE price_list_items (
  price_list_id   TEXT NOT NULL REFERENCES price_lists(id) ON DELETE CASCADE,
  product_unit_id TEXT NOT NULL REFERENCES product_units(id) ON DELETE CASCADE,
  price_minor     INTEGER NOT NULL CHECK (price_minor >= 0),
  markup_bp       INTEGER CHECK (markup_bp IS NULL OR markup_bp BETWEEN -100000 AND 100000),
  updated_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (price_list_id, product_unit_id)
) STRICT;

CREATE INDEX idx_price_list_items_unit ON price_list_items(product_unit_id);

CREATE TABLE registers (
  id                     TEXT PRIMARY KEY,
  name                   TEXT NOT NULL COLLATE NOCASE UNIQUE,
  device_id              TEXT UNIQUE,
  default_price_list_id  TEXT REFERENCES price_lists(id) ON DELETE SET NULL,
  active                 INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
  created_at             TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at             TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
) STRICT;

CREATE INDEX idx_registers_price_list ON registers(default_price_list_id);

CREATE TABLE document_sequences (
  id                 TEXT PRIMARY KEY,
  document_type      TEXT NOT NULL
                     CHECK (document_type IN
                       ('receipt','refund','order','proforma','report','purchase','inventory')),
  register_id        TEXT NOT NULL REFERENCES registers(id) ON DELETE CASCADE,
  period_key         TEXT NOT NULL DEFAULT '',
  prefix             TEXT NOT NULL DEFAULT '',
  next_number        INTEGER NOT NULL DEFAULT 1 CHECK (next_number > 0),
  reset_on_day_close INTEGER NOT NULL DEFAULT 0 CHECK (reset_on_day_close IN (0,1)),
  created_at         TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at         TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  UNIQUE (document_type, register_id, period_key)
) STRICT;

-- ----------------------------------------------------------------------------
-- 5. Customers, discounts, loyalty, promotions
-- ----------------------------------------------------------------------------

CREATE TABLE customers (
  id             TEXT PRIMARY KEY,
  code           TEXT COLLATE NOCASE,
  name           TEXT NOT NULL,
  type           TEXT NOT NULL DEFAULT 'customer'
                 CHECK (type IN ('customer','supplier','both')),
  tax_number     TEXT,
  address        TEXT,
  phone          TEXT,
  email          TEXT,
  price_list_id  TEXT REFERENCES price_lists(id) ON DELETE SET NULL,
  discount_kind  TEXT NOT NULL DEFAULT 'none'
                 CHECK (discount_kind IN ('none','percent','amount')),
  discount_value INTEGER NOT NULL DEFAULT 0 CHECK (discount_value >= 0),
  active         INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
  notes          TEXT,
  created_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CHECK (
    (discount_kind = 'none' AND discount_value = 0)
    OR (discount_kind = 'percent' AND discount_value > 0 AND discount_value <= 10000)
    OR (discount_kind = 'amount' AND discount_value > 0)
  )
) STRICT;

CREATE UNIQUE INDEX ux_customers_code ON customers(code) WHERE code IS NOT NULL;
CREATE INDEX idx_customers_name ON customers(name);
CREATE INDEX idx_customers_price_list ON customers(price_list_id);
CREATE INDEX idx_customers_type ON customers(type, active);

CREATE TABLE discount_rules (
  id             TEXT PRIMARY KEY,
  customer_id    TEXT NOT NULL REFERENCES customers(id) ON DELETE CASCADE,
  scope_type     TEXT NOT NULL CHECK (scope_type IN ('product','group','cart')),
  target_id      TEXT,
  discount_kind  TEXT NOT NULL CHECK (discount_kind IN ('percent','amount')),
  discount_value INTEGER NOT NULL CHECK (discount_value > 0),
  active         INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
  created_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CHECK (
    (discount_kind = 'percent' AND discount_value <= 10000)
    OR (discount_kind = 'amount')
  ),
  CHECK (
    (scope_type = 'cart' AND target_id IS NULL)
    OR (scope_type IN ('product','group') AND target_id IS NOT NULL)
  )
) STRICT;

CREATE INDEX idx_discount_rules_customer ON discount_rules(customer_id, active);
CREATE INDEX idx_discount_rules_target ON discount_rules(scope_type, target_id);

CREATE TABLE loyalty_cards (
  id             TEXT PRIMARY KEY,
  customer_id    TEXT NOT NULL REFERENCES customers(id) ON DELETE CASCADE,
  card_number    TEXT NOT NULL COLLATE NOCASE UNIQUE,
  points_balance INTEGER NOT NULL DEFAULT 0 CHECK (points_balance >= 0),
  active         INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
  created_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
) STRICT;

CREATE INDEX idx_loyalty_cards_customer ON loyalty_cards(customer_id);

CREATE TABLE promotions (
  id             TEXT PRIMARY KEY,
  name           TEXT NOT NULL,
  scope_type     TEXT NOT NULL CHECK (scope_type IN ('product','group','cart')),
  target_id      TEXT,
  discount_kind  TEXT NOT NULL CHECK (discount_kind IN ('percent','amount')),
  discount_value INTEGER NOT NULL CHECK (discount_value > 0),
  starts_at      TEXT,
  ends_at        TEXT,
  days_of_week   TEXT,
  start_time     TEXT,
  end_time       TEXT,
  active         INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
  created_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CHECK (
    (discount_kind = 'percent' AND discount_value <= 10000)
    OR (discount_kind = 'amount')
  ),
  CHECK (
    (scope_type = 'cart' AND target_id IS NULL)
    OR (scope_type IN ('product','group') AND target_id IS NOT NULL)
  )
) STRICT;

CREATE INDEX idx_promotions_active ON promotions(active, starts_at, ends_at);
CREATE INDEX idx_promotions_target ON promotions(scope_type, target_id);

-- ----------------------------------------------------------------------------
-- 6. Payment types and business days
-- ----------------------------------------------------------------------------

CREATE TABLE payment_types (
  id                TEXT PRIMARY KEY,
  name              TEXT NOT NULL COLLATE NOCASE UNIQUE,
  icon              TEXT,
  shortcut          TEXT,
  mark_as_paid      INTEGER NOT NULL DEFAULT 1 CHECK (mark_as_paid IN (0,1)),
  is_default        INTEGER NOT NULL DEFAULT 0 CHECK (is_default IN (0,1)),
  opens_cash_drawer INTEGER NOT NULL DEFAULT 0 CHECK (opens_cash_drawer IN (0,1)),
  active            INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
  sort_order        INTEGER NOT NULL DEFAULT 0,
  created_at        TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at        TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
) STRICT;

CREATE UNIQUE INDEX ux_payment_types_default
  ON payment_types(is_default) WHERE is_default = 1;

CREATE TABLE business_days (
  id                   TEXT PRIMARY KEY,
  register_id          TEXT NOT NULL REFERENCES registers(id) ON DELETE RESTRICT,
  business_date        TEXT NOT NULL,
  status               TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','closed')),
  opened_at            TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  opened_by            TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  closed_at            TEXT,
  closed_by            TEXT REFERENCES users(id) ON DELETE RESTRICT,
  report_number        TEXT,
  opening_cash_minor   INTEGER NOT NULL DEFAULT 0 CHECK (opening_cash_minor >= 0),
  closing_cash_minor   INTEGER CHECK (closing_cash_minor IS NULL OR closing_cash_minor >= 0),
  expected_cash_minor  INTEGER CHECK (expected_cash_minor IS NULL OR expected_cash_minor >= 0),
  variance_minor       INTEGER,
  sales_count          INTEGER NOT NULL DEFAULT 0 CHECK (sales_count >= 0),
  refund_count         INTEGER NOT NULL DEFAULT 0 CHECK (refund_count >= 0),
  taxable_total_minor  INTEGER NOT NULL DEFAULT 0 CHECK (taxable_total_minor >= 0),
  tax_total_minor      INTEGER NOT NULL DEFAULT 0 CHECK (tax_total_minor >= 0),
  discount_total_minor INTEGER NOT NULL DEFAULT 0 CHECK (discount_total_minor >= 0),
  grand_total_minor    INTEGER NOT NULL DEFAULT 0 CHECK (grand_total_minor >= 0),
  refund_total_minor   INTEGER NOT NULL DEFAULT 0 CHECK (refund_total_minor >= 0),
  cash_in_total_minor  INTEGER NOT NULL DEFAULT 0 CHECK (cash_in_total_minor >= 0),
  cash_out_total_minor INTEGER NOT NULL DEFAULT 0 CHECK (cash_out_total_minor >= 0),
  created_at           TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at           TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
) STRICT;

CREATE INDEX idx_business_days_register_date ON business_days(register_id, business_date);
CREATE UNIQUE INDEX ux_business_days_open
  ON business_days(register_id) WHERE status = 'open';
CREATE UNIQUE INDEX ux_business_days_report
  ON business_days(report_number) WHERE report_number IS NOT NULL;

-- ----------------------------------------------------------------------------
-- 7. Sales, line items, taxes, payments
-- ----------------------------------------------------------------------------

CREATE TABLE sales (
  id                  TEXT PRIMARY KEY,
  number              TEXT NOT NULL UNIQUE,
  type                TEXT NOT NULL DEFAULT 'sale'
                      CHECK (type IN ('sale','refund','proforma')),
  status              TEXT NOT NULL DEFAULT 'open'
                      CHECK (status IN ('open','closed','voided','refunded','partially_refunded')),
  parent_sale_id      TEXT REFERENCES sales(id) ON DELETE RESTRICT,
  client_request_id   TEXT,
  register_id         TEXT NOT NULL REFERENCES registers(id) ON DELETE RESTRICT,
  business_day_id     TEXT REFERENCES business_days(id) ON DELETE SET NULL,
  user_id             TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  customer_id         TEXT REFERENCES customers(id) ON DELETE SET NULL,
  customer_name_snapshot       TEXT,
  customer_tax_number_snapshot TEXT,
  price_list_id       TEXT REFERENCES price_lists(id) ON DELETE RESTRICT,
  currency            TEXT NOT NULL DEFAULT 'IDR',
  currency_minor_unit INTEGER NOT NULL DEFAULT 0
                      CHECK (currency_minor_unit BETWEEN 0 AND 4),
  subtotal_minor      INTEGER NOT NULL DEFAULT 0 CHECK (subtotal_minor >= 0),
  discount_kind       TEXT NOT NULL DEFAULT 'none'
                      CHECK (discount_kind IN ('none','percent','amount')),
  discount_value      INTEGER NOT NULL DEFAULT 0 CHECK (discount_value >= 0),
  discount_total_minor INTEGER NOT NULL DEFAULT 0 CHECK (discount_total_minor >= 0),
  tax_total_minor     INTEGER NOT NULL DEFAULT 0 CHECK (tax_total_minor >= 0),
  total_minor         INTEGER NOT NULL DEFAULT 0 CHECK (total_minor >= 0),
  paid_total_minor    INTEGER NOT NULL DEFAULT 0 CHECK (paid_total_minor >= 0),
  change_minor        INTEGER NOT NULL DEFAULT 0 CHECK (change_minor >= 0),
  balance_minor       INTEGER NOT NULL DEFAULT 0 CHECK (balance_minor >= 0),
  refunded_total_minor INTEGER NOT NULL DEFAULT 0 CHECK (refunded_total_minor >= 0),
  due_date            TEXT,
  note                TEXT,
  void_reason         TEXT,
  created_at          TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at          TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  closed_at           TEXT,
  CHECK (
    (discount_kind = 'none' AND discount_value = 0)
    OR (discount_kind = 'percent' AND discount_value > 0 AND discount_value <= 10000)
    OR (discount_kind = 'amount' AND discount_value > 0)
  )
) STRICT;

CREATE INDEX idx_sales_business_day ON sales(business_day_id);
CREATE INDEX idx_sales_customer ON sales(customer_id);
CREATE INDEX idx_sales_user ON sales(user_id);
CREATE INDEX idx_sales_register ON sales(register_id);
CREATE INDEX idx_sales_status_created ON sales(status, created_at);
CREATE INDEX idx_sales_type_created ON sales(type, created_at);
CREATE INDEX idx_sales_parent ON sales(parent_sale_id);
CREATE INDEX idx_sales_price_list ON sales(price_list_id);
CREATE UNIQUE INDEX ux_sales_client_request
  ON sales(client_request_id) WHERE client_request_id IS NOT NULL;

CREATE TABLE sale_items (
  id                     TEXT PRIMARY KEY,
  sale_id                TEXT NOT NULL REFERENCES sales(id) ON DELETE CASCADE,
  product_id             TEXT REFERENCES products(id) ON DELETE SET NULL,
  product_unit_id        TEXT REFERENCES product_units(id) ON DELETE SET NULL,
  original_sale_item_id  TEXT REFERENCES sale_items(id) ON DELETE SET NULL,
  name_snapshot          TEXT NOT NULL,
  code_snapshot          TEXT,
  unit_name_snapshot     TEXT NOT NULL,
  unit_factor_milli      INTEGER NOT NULL CHECK (unit_factor_milli > 0),
  qty_milli              INTEGER NOT NULL CHECK (qty_milli > 0),
  base_qty_milli         INTEGER NOT NULL CHECK (base_qty_milli > 0),
  unit_price_minor       INTEGER NOT NULL CHECK (unit_price_minor >= 0),
  unit_cost_minor        INTEGER NOT NULL DEFAULT 0 CHECK (unit_cost_minor >= 0),
  discount_kind          TEXT NOT NULL DEFAULT 'none'
                         CHECK (discount_kind IN ('none','percent','amount')),
  discount_value         INTEGER NOT NULL DEFAULT 0 CHECK (discount_value >= 0),
  discount_total_minor   INTEGER NOT NULL DEFAULT 0 CHECK (discount_total_minor >= 0),
  tax_total_minor        INTEGER NOT NULL DEFAULT 0 CHECK (tax_total_minor >= 0),
  line_total_minor       INTEGER NOT NULL DEFAULT 0 CHECK (line_total_minor >= 0),
  status                 TEXT NOT NULL DEFAULT 'confirmed'
                         CHECK (status IN ('added','confirmed','voided')),
  tax_override           INTEGER NOT NULL DEFAULT 0 CHECK (tax_override IN (0,1)),
  refunded_qty_milli     INTEGER NOT NULL DEFAULT 0 CHECK (refunded_qty_milli >= 0),
  comment                TEXT,
  sort_order             INTEGER NOT NULL DEFAULT 0,
  created_at             TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at             TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CHECK (
    (discount_kind = 'none' AND discount_value = 0)
    OR (discount_kind = 'percent' AND discount_value > 0 AND discount_value <= 10000)
    OR (discount_kind = 'amount' AND discount_value > 0)
  ),
  CHECK (refunded_qty_milli <= qty_milli)
) STRICT;

CREATE INDEX idx_sale_items_sale ON sale_items(sale_id);
CREATE INDEX idx_sale_items_product ON sale_items(product_id);
CREATE INDEX idx_sale_items_unit ON sale_items(product_unit_id);
CREATE INDEX idx_sale_items_status ON sale_items(status);
CREATE INDEX idx_sale_items_original ON sale_items(original_sale_item_id);

CREATE TABLE sale_item_taxes (
  id                 TEXT PRIMARY KEY,
  sale_item_id       TEXT NOT NULL REFERENCES sale_items(id) ON DELETE CASCADE,
  tax_rate_id        TEXT REFERENCES tax_rates(id) ON DELETE SET NULL,
  name_snapshot      TEXT NOT NULL,
  rate_bp            INTEGER NOT NULL CHECK (rate_bp >= 0),
  taxable_base_minor INTEGER NOT NULL CHECK (taxable_base_minor >= 0),
  amount_minor       INTEGER NOT NULL CHECK (amount_minor >= 0),
  created_at         TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
) STRICT;

CREATE INDEX idx_sale_item_taxes_item ON sale_item_taxes(sale_item_id);
CREATE INDEX idx_sale_item_taxes_rate ON sale_item_taxes(tax_rate_id);

CREATE TABLE payments (
  id              TEXT PRIMARY KEY,
  sale_id         TEXT NOT NULL REFERENCES sales(id) ON DELETE CASCADE,
  payment_type_id TEXT NOT NULL REFERENCES payment_types(id) ON DELETE RESTRICT,
  kind            TEXT NOT NULL DEFAULT 'tender'
                  CHECK (kind IN ('tender','credit_settlement','refund')),
  amount_minor    INTEGER NOT NULL CHECK (amount_minor > 0),
  tendered_minor  INTEGER NOT NULL DEFAULT 0 CHECK (tendered_minor >= 0),
  change_minor    INTEGER NOT NULL DEFAULT 0 CHECK (change_minor >= 0),
  reference       TEXT,
  status          TEXT NOT NULL DEFAULT 'captured'
                  CHECK (status IN ('captured','voided')),
  created_by      TEXT REFERENCES users(id) ON DELETE SET NULL,
  created_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
) STRICT;

CREATE INDEX idx_payments_sale ON payments(sale_id);
CREATE INDEX idx_payments_type ON payments(payment_type_id);
CREATE INDEX idx_payments_created ON payments(created_at);
CREATE INDEX idx_payments_kind ON payments(kind, created_at);

-- ----------------------------------------------------------------------------
-- 8. Cash, stock, inventory, purchases
-- ----------------------------------------------------------------------------

CREATE TABLE cash_movements (
  id              TEXT PRIMARY KEY,
  register_id     TEXT NOT NULL REFERENCES registers(id) ON DELETE RESTRICT,
  business_day_id TEXT NOT NULL REFERENCES business_days(id) ON DELETE RESTRICT,
  user_id         TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  direction       TEXT NOT NULL CHECK (direction IN ('in','out')),
  amount_minor    INTEGER NOT NULL CHECK (amount_minor > 0),
  reason          TEXT NOT NULL,
  created_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
) STRICT;

CREATE INDEX idx_cash_movements_day ON cash_movements(business_day_id);
CREATE INDEX idx_cash_movements_user ON cash_movements(user_id);

CREATE TABLE stock_movements (
  id                   TEXT PRIMARY KEY,
  product_id           TEXT NOT NULL REFERENCES products(id) ON DELETE RESTRICT,
  type                 TEXT NOT NULL
                       CHECK (type IN
                         ('opening','sale','refund','purchase','adjustment','inventory','loss','return')),
  qty_delta_base_milli INTEGER NOT NULL CHECK (qty_delta_base_milli <> 0),
  unit_cost_minor      INTEGER CHECK (unit_cost_minor IS NULL OR unit_cost_minor >= 0),
  reference_type       TEXT,
  reference_id         TEXT,
  note                 TEXT,
  user_id              TEXT REFERENCES users(id) ON DELETE SET NULL,
  created_at           TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
) STRICT;

CREATE INDEX idx_stock_movements_product_created
  ON stock_movements(product_id, created_at);
CREATE INDEX idx_stock_movements_reference
  ON stock_movements(reference_type, reference_id);
CREATE INDEX idx_stock_movements_created ON stock_movements(created_at);

CREATE TABLE inventory_counts (
  id          TEXT PRIMARY KEY,
  number      TEXT UNIQUE,
  status      TEXT NOT NULL DEFAULT 'draft'
              CHECK (status IN ('draft','posted','voided')),
  counted_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  user_id     TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  note        TEXT,
  created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
) STRICT;

CREATE INDEX idx_inventory_counts_status ON inventory_counts(status, counted_at);

CREATE TABLE inventory_count_items (
  id                     TEXT PRIMARY KEY,
  inventory_count_id     TEXT NOT NULL REFERENCES inventory_counts(id) ON DELETE CASCADE,
  product_id             TEXT NOT NULL REFERENCES products(id) ON DELETE RESTRICT,
  expected_base_milli    INTEGER NOT NULL,
  counted_base_milli     INTEGER NOT NULL,
  variance_base_milli    INTEGER NOT NULL,
  unit_cost_minor        INTEGER CHECK (unit_cost_minor IS NULL OR unit_cost_minor >= 0),
  created_at             TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  UNIQUE (inventory_count_id, product_id),
  CHECK (variance_base_milli = counted_base_milli - expected_base_milli)
) STRICT;

CREATE INDEX idx_inventory_count_items_product ON inventory_count_items(product_id);

CREATE TABLE purchases (
  id             TEXT PRIMARY KEY,
  number         TEXT NOT NULL UNIQUE,
  supplier_id    TEXT REFERENCES customers(id) ON DELETE SET NULL,
  status         TEXT NOT NULL DEFAULT 'draft'
                 CHECK (status IN ('draft','received','voided')),
  purchased_at   TEXT NOT NULL,
  subtotal_minor INTEGER NOT NULL DEFAULT 0 CHECK (subtotal_minor >= 0),
  tax_total_minor INTEGER NOT NULL DEFAULT 0 CHECK (tax_total_minor >= 0),
  total_minor    INTEGER NOT NULL DEFAULT 0 CHECK (total_minor >= 0),
  note           TEXT,
  user_id        TEXT REFERENCES users(id) ON DELETE SET NULL,
  created_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
) STRICT;

CREATE INDEX idx_purchases_supplier ON purchases(supplier_id);
CREATE INDEX idx_purchases_date ON purchases(purchased_at);

CREATE TABLE purchase_items (
  id                 TEXT PRIMARY KEY,
  purchase_id        TEXT NOT NULL REFERENCES purchases(id) ON DELETE CASCADE,
  product_id         TEXT NOT NULL REFERENCES products(id) ON DELETE RESTRICT,
  product_unit_id    TEXT REFERENCES product_units(id) ON DELETE SET NULL,
  unit_name_snapshot TEXT NOT NULL,
  unit_factor_milli  INTEGER NOT NULL CHECK (unit_factor_milli > 0),
  qty_milli          INTEGER NOT NULL CHECK (qty_milli > 0),
  base_qty_milli     INTEGER NOT NULL CHECK (base_qty_milli > 0),
  unit_cost_minor    INTEGER NOT NULL CHECK (unit_cost_minor >= 0),
  tax_amount_minor   INTEGER NOT NULL DEFAULT 0 CHECK (tax_amount_minor >= 0),
  line_total_minor   INTEGER NOT NULL DEFAULT 0 CHECK (line_total_minor >= 0),
  created_at         TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
) STRICT;

CREATE INDEX idx_purchase_items_purchase ON purchase_items(purchase_id);
CREATE INDEX idx_purchase_items_product ON purchase_items(product_id);

-- ----------------------------------------------------------------------------
-- 9. Audit, printing, backups
-- ----------------------------------------------------------------------------

CREATE TABLE audit_events (
  id            TEXT PRIMARY KEY,
  actor_user_id TEXT REFERENCES users(id) ON DELETE RESTRICT,
  action        TEXT NOT NULL,
  entity_type   TEXT NOT NULL,
  entity_id     TEXT,
  details_json  TEXT NOT NULL DEFAULT '{}',
  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
) STRICT;

CREATE INDEX idx_audit_entity ON audit_events(entity_type, entity_id, created_at);
CREATE INDEX idx_audit_actor ON audit_events(actor_user_id, created_at);
CREATE INDEX idx_audit_created ON audit_events(created_at);

CREATE TRIGGER audit_events_no_update
BEFORE UPDATE ON audit_events
BEGIN
  SELECT RAISE(ABORT, 'audit_events is append-only');
END;

CREATE TRIGGER audit_events_no_delete
BEFORE DELETE ON audit_events
BEGIN
  SELECT RAISE(ABORT, 'audit_events is append-only');
END;

CREATE TABLE print_events (
  id               TEXT PRIMARY KEY,
  sale_id          TEXT REFERENCES sales(id) ON DELETE SET NULL,
  business_day_id  TEXT REFERENCES business_days(id) ON DELETE SET NULL,
  document_type    TEXT NOT NULL
                   CHECK (document_type IN
                     ('receipt','invoice','refund','x_report','z_report','report')),
  printer_name     TEXT,
  status           TEXT NOT NULL CHECK (status IN ('queued','printed','failed')),
  error            TEXT,
  created_by       TEXT REFERENCES users(id) ON DELETE SET NULL,
  created_at       TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at       TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
) STRICT;

CREATE INDEX idx_print_events_sale ON print_events(sale_id);
CREATE INDEX idx_print_events_day ON print_events(business_day_id);
CREATE INDEX idx_print_events_created ON print_events(created_at);

CREATE TABLE backup_runs (
  id         TEXT PRIMARY KEY,
  path       TEXT NOT NULL,
  size_bytes INTEGER NOT NULL DEFAULT 0 CHECK (size_bytes >= 0),
  status     TEXT NOT NULL CHECK (status IN ('success','failed')),
  error      TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
) STRICT;

CREATE INDEX idx_backup_runs_created ON backup_runs(created_at);

-- ----------------------------------------------------------------------------
-- 10. Views used by the UI and reports
-- ----------------------------------------------------------------------------

CREATE VIEW v_stock_on_hand AS
SELECT
  p.id                              AS product_id,
  p.name,
  p.code,
  bu.name                           AS base_unit,
  COALESCE(SUM(sm.qty_delta_base_milli), 0) AS qty_base_milli
FROM products p
LEFT JOIN product_units bpu
  ON bpu.product_id = p.id AND bpu.is_base = 1
LEFT JOIN units bu ON bu.id = bpu.unit_id
LEFT JOIN stock_movements sm ON sm.product_id = p.id
GROUP BY p.id, p.name, p.code, bu.name;

CREATE VIEW v_price_list_prices AS
SELECT
  pl.id          AS price_list_id,
  pl.name        AS price_list_name,
  p.id           AS product_id,
  p.name         AS product_name,
  p.code         AS product_code,
  pu.id          AS product_unit_id,
  u.name         AS unit_name,
  pu.factor_to_base_milli,
  pu.is_default_sale,
  COALESCE(
    pli.price_minor,
    pu.price_minor,
    (p.price_minor * pu.factor_to_base_milli + 500) / 1000
  ) AS price_minor,
  CASE WHEN pli.product_unit_id IS NULL THEN 1 ELSE 0 END AS is_inherited,
  pli.markup_bp
FROM price_lists pl
CROSS JOIN product_units pu
JOIN products p ON p.id = pu.product_id
JOIN units u ON u.id = pu.unit_id
LEFT JOIN price_list_items pli
  ON pli.price_list_id = pl.id AND pli.product_unit_id = pu.id
WHERE pl.active = 1 AND p.active = 1 AND pu.active = 1;

CREATE VIEW v_open_sales AS
SELECT
  s.*,
  u.full_name AS user_name,
  c.name      AS customer_name,
  r.name      AS register_name
FROM sales s
JOIN users u     ON u.id = s.user_id
JOIN registers r ON r.id = s.register_id
LEFT JOIN customers c ON c.id = s.customer_id
WHERE s.status = 'open';

